// lib/prisma.ts
import { PrismaClient, Prisma } from '@prisma/client';
import { getSession } from 'next-auth/react';

const prisma = new PrismaClient();

// Prisma middleware to log create, update, delete operations
prisma.$use(async (params, next) => {
  const result = await next(params);

  // Only log mutations on Ticket and Response models
  const modelsToAudit = ['Ticket', 'Response'];
  if (!modelsToAudit.includes(params.model)) return result;

  const operation = params.action; // create, update, delete, etc.
  if (!['create', 'update', 'delete'].includes(operation)) return result;

  // Retrieve user ID from session (if available)
  const session = await getSession();
  const userId = session?.user?.id ? Number(session.user.id) : null;

  // Prepare payload
  const payload = operation === 'delete' ? null : result;

  // Insert audit record
  await prisma.auditLog.create({
    data: {
      model: params.model,
      operation,
      recordId: Array.isArray(result) ? result[0].id : result.id,
      userId,
      payload,
    },
  });

  return result;
});

export default prisma;
