import { Box, Heading, Spinner, Center, Text } from '@chakra-ui/react';
import { useRouter } from 'next/router';
import { useEffect } from 'react';
import { useSWR } from 'swr';
import { fetcher } from '../../utils/fetcher';
import { AnalyticsData } from '../../types';

const ResponseTimeChart = dynamic(() => import('../../components/ResponseTimeChart'), {
  ssr: false,
  loading: () => <Spinner size="lg" />,
});

export default function AnalyticsPage() {
  const { data: session, status } = useSession();
  const router = useRouter();

  // Redirect to login if not authenticated
  useEffect(() => {
    if (status === 'unauthenticated') router.replace('/api/auth/signin');
  }, [status, router]);

  const { data, error } = useSWR<AnalyticsData[]>('/api/analytics/response-time', fetcher);

  if (status === 'loading' || !data) {
    return (
      <Center h="100vh">
        <Spinner size="xl" />
      </Center>
    );
  }

  if (error) {
    return (
      <Center h="100vh">
        <Text color="red.500">Failed to load analytics data.</Text>
      </Center>
    );
  }

  return (
    <Box p={8}>
      <Heading mb={6}>Response Time Analytics</Heading>
      <ResponseTimeChart data={data} />
    </Box>
  );
}

export const getServerSideProps: GetServerSideProps = async (ctx) => {
  // Ensure user is authenticated on the server side
  const session = await getSession(ctx);
  if (!session) {
    return {
      redirect: {
        destination: '/api/auth/signin',
        permanent: false,
      },
    };
  }
  return { props: {} };
};
